/* MIC multi-asset catalog loader.
 * Preserves curated ETF/crypto records and loads the complete official
 * Nasdaq-listed symbol directory generated by GitHub Actions.
 */
(() => {
  if (window.__MIC_ASSET_CATALOG_V24) return;
  window.__MIC_ASSET_CATALOG_V24 = true;

  const desktop=location.pathname.includes('mic-desktop');
  const base=desktop?'../mic/':'';
  const keyOf=a=>String(a.type||'').toLowerCase()==='crypto'
    ? `CRYPTO:${String(a.symbol||'').toUpperCase()}`
    : `${String(a.exchange||'').toUpperCase()}:${String(a.symbol||'').toUpperCase()}`;
  let loadingPromise=null;

  function mergeAssets(primary, supplemental){
    const merged=new Map();
    (primary||[]).forEach(a=>merged.set(keyOf(a),a));
    (supplemental||[]).forEach(s=>{
      const key=keyOf(s),current=merged.get(key)||{};
      merged.set(key,{...s,...current,
        symbol:current.symbol||s.symbol,
        name:current.name||s.name,
        type:current.type||s.type,
        exchange:current.exchange||s.exchange,
        currency:current.currency||s.currency,
        provider_symbol:current.provider_symbol||s.provider_symbol,
        search_aliases:[...new Set([...(s.search_aliases||[]),...(current.search_aliases||[])])],
        history:Array.isArray(current.history)&&current.history.length?current.history:(s.history||[]),
        performance:Object.keys(current.performance||{}).length?current.performance:(s.performance||{})
      });
    });
    return [...merged.values()];
  }

  async function fetchCatalog(path){
    const response=await fetch(base+path+'?t='+Date.now(),{cache:'no-store'});
    if(!response.ok)throw new Error(`${path}: HTTP ${response.status}`);
    return response.json();
  }

  async function applyAllCatalogs(){
    if(loadingPromise)return loadingPromise;
    loadingPromise=(async()=>{
      const [nasdaqResult,supplementalResult]=await Promise.allSettled([
        fetchCatalog('data/nasdaq-assets.json'),
        fetchCatalog('data/supplemental-assets.json')
      ]);
      let loaded=0,nasdaqCount=0,supplementalCount=0;
      if(nasdaqResult.status==='fulfilled'){
        const catalog=nasdaqResult.value;
        market.assets=mergeAssets(market.assets,catalog.assets);
        nasdaqCount=catalog.assets?.length||0;loaded+=nasdaqCount;
      }else console.error('MIC Nasdaq catalog could not be loaded',nasdaqResult.reason);
      if(supplementalResult.status==='fulfilled'){
        const catalog=supplementalResult.value;
        market.assets=mergeAssets(market.assets,catalog.assets);
        supplementalCount=catalog.assets?.length||0;loaded+=supplementalCount;
      }else console.error('MIC supplemental catalog could not be loaded',supplementalResult.reason);
      const status=$('settingsStatus');
      if(status)status.textContent=`${market.assets.length} varlık yüklendi; Nasdaq ${nasdaqCount}, tamamlayıcı ETF/kripto ${supplementalCount}.`;
      if(typeof runSearch==='function')runSearch();
      if(typeof renderPortfolio==='function')renderPortfolio();
      window.MIC_ASSET_CATALOG_STATUS={ok:loaded>0,count:loaded,nasdaqCount,supplementalCount};
      document.dispatchEvent(new CustomEvent('mic:asset-catalog-ready',{detail:window.MIC_ASSET_CATALOG_STATUS}));
      return loaded>0;
    })().finally(()=>{loadingPromise=null});
    return loadingPromise;
  }

  const originalLoadMarket=window.loadMarket;
  if(typeof originalLoadMarket==='function'){
    window.loadMarket=async function(){
      const result=await originalLoadMarket.apply(this,arguments);
      await applyAllCatalogs();
      return result;
    };
  }

  setTimeout(applyAllCatalogs,0);
})();
